package dev.saffron;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import static org.springframework.http.HttpStatus.*;
@Service class Addresses {
 private final JdbcTemplate db;Addresses(JdbcTemplate db){this.db=db;}
 record Input(String label,String recipient,String line1,String line2,String city,String postalCode,Double latitude,Double longitude){}
 record Snapshot(UUID id,long version,String label,String recipient,String line1,String line2,String city,String postalCode,double latitude,double longitude){}
 static String text(String value,int min,int max){if(value==null)throw new IllegalArgumentException("Address fields required");String s=value.strip();if(s.length()<min||s.length()>max||s.codePoints().anyMatch(Character::isISOControl))throw new IllegalArgumentException("Invalid address field length or control characters");return s;}
 static Input validate(Input input){if(input==null)throw new IllegalArgumentException("Address required");if(input.latitude==null||input.longitude==null||!Double.isFinite(input.latitude)||!Double.isFinite(input.longitude)||Math.abs(input.latitude)>90||Math.abs(input.longitude)>180)throw new IllegalArgumentException("Valid address coordinates required");String postal=text(input.postalCode,3,12);if(!postal.matches("[a-zA-Z0-9 -]+"))throw new IllegalArgumentException("Invalid postal code");return new Input(text(input.label,1,50),text(input.recipient,2,100),text(input.line1,5,200),text(input.line2==null?"":input.line2,0,200),text(input.city,2,80),postal,input.latitude,input.longitude);}
 List<Snapshot> list(String user){return db.query("select *,ST_Y(location::geometry) lat,ST_X(location::geometry) lon from customer_addresses where customer_subject=? and deleted_at is null order by updated_at desc limit 20",(rs,n)->new Snapshot(rs.getObject("id",UUID.class),rs.getLong("version"),rs.getString("label"),rs.getString("recipient"),rs.getString("line1"),rs.getString("line2"),rs.getString("city"),rs.getString("postal_code"),rs.getDouble("lat"),rs.getDouble("lon")),user);}
 Snapshot owned(String user,UUID id,boolean lock){var rows=db.query("select *,ST_Y(location::geometry) lat,ST_X(location::geometry) lon from customer_addresses where customer_subject=? and id=? and deleted_at is null"+(lock?" for share":""),(rs,n)->new Snapshot(rs.getObject("id",UUID.class),rs.getLong("version"),rs.getString("label"),rs.getString("recipient"),rs.getString("line1"),rs.getString("line2"),rs.getString("city"),rs.getString("postal_code"),rs.getDouble("lat"),rs.getDouble("lon")),user,id);if(rows.isEmpty())throw new ResponseStatusException(NOT_FOUND,"Address not found");return rows.getFirst();}
 @Transactional public Snapshot create(String user,Input raw){var input=validate(raw);db.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"addresses:"+user);if(list(user).size()>=20)throw new ResponseStatusException(CONFLICT,"At most 20 saved addresses");UUID id=UUID.randomUUID();db.update("insert into customer_addresses(id,customer_subject,label,recipient,line1,line2,city,postal_code,location) values(?,?,?,?,?,?,?,?,ST_SetSRID(ST_Point(?,?),4326)::geography)",id,user,input.label,input.recipient,input.line1,input.line2,input.city,input.postalCode,input.longitude,input.latitude);audit(user,"ADDRESS_CREATED",id);return owned(user,id,false);}
 @Transactional public Snapshot update(String user,UUID id,long version,Input raw){var input=validate(raw);owned(user,id,false);if(db.update("update customer_addresses set label=?,recipient=?,line1=?,line2=?,city=?,postal_code=?,location=ST_SetSRID(ST_Point(?,?),4326)::geography,version=version+1,updated_at=now() where id=? and customer_subject=? and version=? and deleted_at is null",input.label,input.recipient,input.line1,input.line2,input.city,input.postalCode,input.longitude,input.latitude,id,user,version)!=1)throw new ResponseStatusException(CONFLICT,"Address changed; refresh first");audit(user,"ADDRESS_UPDATED",id);return owned(user,id,false);}
 @Transactional public void delete(String user,UUID id,long version){owned(user,id,false);if(db.update("update customer_addresses set deleted_at=now(),version=version+1 where customer_subject=? and id=? and version=? and deleted_at is null",user,id,version)!=1)throw new ResponseStatusException(CONFLICT,"Address changed; refresh first");audit(user,"ADDRESS_DELETED",id);}
 private void audit(String user,String action,UUID id){db.update("insert into audit(actor,action,resource) values(?,?,?)",user,action,id.toString());}
}
